// DbSession implementation for Redis.
//
// * Databases db0…dbN are the catalogs.
// * The navigator lists key "folders" (keys grouped by the prefix before the
//   separator, e.g. `user:*`) and the keys without separator, from a bounded
//   SCAN (never KEYS *).
// * `SELECT * FROM <key>` shows the content of a key according to its type,
//   `SELECT * FROM <pattern>` lists the matching keys with type, TTL and size
//   (SCAN based, paged with fetchMore). WHERE / ORDER BY / LIMIT are applied
//   client side; UPDATE / INSERT / DELETE generated by the grid are mapped to
//   the type-specific commands (HSET, LSET, SADD, ZADD, DEL…).
// * Any other text is run as Redis commands, one per line.
import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:math';
import 'dart:typed_data';

import '../../odbc/odbc_ffi.dart';
import '../../odbc/odbc_types.dart';
import '../common/aws_sigv4.dart';
import '../common/native_exception.dart';
import '../common/native_session_base.dart';
import '../common/net.dart';
import '../common/relaxed_json.dart';
import '../common/sql_subset.dart';
import '../db_session.dart';
import '../native_driver.dart';
import 'redis_connection.dart';
import 'resp.dart';

const redisDriverVersion = '1.0.0';

/// Connection settings resolved from the dialog / URI.
class RedisSettings {
  RedisSettings({
    required this.host,
    required this.port,
    required this.net,
    this.user = '',
    this.password = '',
    this.database = 0,
    this.separator = ':',
    this.scanLimit = 5000,
    this.clientName = 'DbCraft',
    this.authMethod = 'password',
    this.options = const {},
  });

  final String host;
  final int port;
  final NetOptions net;
  final String user;
  final String password;
  final int database;
  final String separator;
  final int scanLimit;
  final String clientName;
  final String authMethod;
  final Map<String, String> options;

  String opt(String k) => options[k] ?? '';

  static RedisSettings from(NativeConnectParams p) {
    var host = p.host.trim().isEmpty ? 'localhost' : p.host.trim();
    var port = int.tryParse(p.port.trim()) ?? 6379;
    var user = p.user;
    var password = p.password;
    var db = int.tryParse(p.database.trim().replaceFirst(RegExp('^db'), '')) ?? 0;
    var tls = p.flag('tls');
    final uriText = p.connectionUri.trim().isNotEmpty ? p.connectionUri.trim() : (host.startsWith('redis') ? host : '');
    if (uriText.isNotEmpty) {
      final u = Uri.parse(uriText);
      if (u.scheme != 'redis' && u.scheme != 'rediss') {
        throw NativeDbException('URI Redis non valido: usa redis:// o rediss://');
      }
      tls = u.scheme == 'rediss';
      host = u.host.isEmpty ? 'localhost' : u.host;
      if (u.hasPort) port = u.port;
      if (u.userInfo.isNotEmpty) {
        final i = u.userInfo.indexOf(':');
        final a = Uri.decodeComponent(i < 0 ? u.userInfo : u.userInfo.substring(0, i));
        final b = i < 0 ? '' : Uri.decodeComponent(u.userInfo.substring(i + 1));
        // redis://:password@host and redis://password@host (legacy) forms.
        if (i < 0) {
          password = a;
        } else {
          user = a;
          password = b;
        }
      }
      final seg = u.pathSegments.where((e) => e.isNotEmpty);
      if (seg.isNotEmpty) db = int.tryParse(seg.first) ?? db;
      if (u.queryParameters['db'] != null) db = int.tryParse(u.queryParameters['db']!) ?? db;
    }
    return RedisSettings(
      host: host,
      port: port,
      net: NetOptions(
        tls: tls,
        caFile: p.option('tlsCaFile'),
        allowInvalidCertificates: p.flag('tlsAllowInvalid'),
        certFile: p.option('tlsCertFile'),
        keyFile: p.option('tlsCertFile'),
        keyPassword: p.option('tlsKeyPassword'),
        timeout: Duration(seconds: p.loginTimeoutSec <= 0 ? 15 : p.loginTimeoutSec),
      ),
      user: user,
      password: password,
      database: db,
      separator: p.option('separator', ':'),
      scanLimit: int.tryParse(p.option('scanLimit', '5000')) ?? 5000,
      clientName: p.option('clientName', 'DbCraft'),
      authMethod: p.option('authMethod', 'password'),
      options: p.options,
    );
  }
}

/// Commands that modify data (blocked on read-only connections).
const redisWriteCommands = {
  'SET', 'SETNX', 'SETEX', 'PSETEX', 'MSET', 'MSETNX', 'APPEND', 'INCR', 'INCRBY', 'INCRBYFLOAT', 'DECR', //
  'DECRBY', 'GETSET', 'GETDEL', 'GETEX', 'SETRANGE', 'SETBIT', 'BITOP', 'BITFIELD', 'DEL', 'UNLINK', 'EXPIRE',
  'PEXPIRE', 'EXPIREAT', 'PEXPIREAT', 'PERSIST', 'RENAME', 'RENAMENX', 'MOVE', 'COPY', 'RESTORE', 'MIGRATE',
  'HSET', 'HSETNX', 'HMSET', 'HDEL', 'HINCRBY', 'HINCRBYFLOAT', 'HEXPIRE', 'HPEXPIRE', 'HPERSIST', 'HGETDEL',
  'HGETEX', 'HSETEX', 'LPUSH', 'RPUSH', 'LPUSHX', 'RPUSHX', 'LPOP', 'RPOP', 'LSET', 'LREM', 'LTRIM', 'LINSERT',
  'LMOVE', 'BLMOVE', 'RPOPLPUSH', 'BRPOPLPUSH', 'BLPOP', 'BRPOP', 'LMPOP', 'BLMPOP', 'SADD', 'SREM', 'SPOP',
  'SMOVE', 'SINTERSTORE', 'SUNIONSTORE', 'SDIFFSTORE', 'ZADD', 'ZREM', 'ZINCRBY', 'ZPOPMIN', 'ZPOPMAX',
  'BZPOPMIN', 'BZPOPMAX', 'ZMPOP', 'BZMPOP', 'ZREMRANGEBYSCORE', 'ZREMRANGEBYRANK', 'ZREMRANGEBYLEX',
  'ZUNIONSTORE', 'ZINTERSTORE', 'ZDIFFSTORE', 'ZRANGESTORE', 'XADD', 'XDEL', 'XTRIM', 'XGROUP', 'XACK',
  'XCLAIM', 'XAUTOCLAIM', 'XSETID', 'XREADGROUP', 'PFADD', 'PFMERGE', 'GEOADD', 'GEOSEARCHSTORE', 'FLUSHDB',
  'FLUSHALL', 'SWAPDB', 'EVAL', 'EVALSHA', 'FCALL', 'SCRIPT', 'FUNCTION', 'SHUTDOWN', 'DEBUG', 'BGSAVE',
  'SAVE', 'BGREWRITEAOF', 'REPLICAOF', 'SLAVEOF', 'FAILOVER', 'JSON.SET', 'JSON.DEL', 'JSON.FORGET',
  'JSON.MSET', 'JSON.MERGE', 'JSON.NUMINCRBY', 'JSON.ARRAPPEND', 'JSON.ARRINSERT', 'JSON.ARRPOP', 'JSON.ARRTRIM',
  'JSON.STRAPPEND', 'JSON.TOGGLE', 'JSON.CLEAR',
};

/// Sub-commands that modify the server configuration / ACL.
const _writeSubcommands = {
  'CONFIG': {'SET', 'REWRITE', 'RESETSTAT'},
  'ACL': {'SETUSER', 'DELUSER', 'LOAD', 'SAVE'},
  'CLIENT': {'KILL', 'PAUSE', 'NO-EVICT'},
  'CLUSTER': {'ADDSLOTS', 'DELSLOTS', 'FAILOVER', 'FORGET', 'MEET', 'RESET', 'SETSLOT', 'FLUSHSLOTS'},
  'MODULE': {'LOAD', 'UNLOAD', 'LOADEX'},
  'SLOWLOG': {'RESET'},
  'LATENCY': {'RESET'},
};

/// Commands that would take over the connection.
const _unsupportedCommands = {'SUBSCRIBE', 'PSUBSCRIBE', 'SSUBSCRIBE', 'MONITOR', 'SYNC', 'PSYNC', 'QUIT', 'RESET'};

class RedisSession extends NativeSessionBase {
  RedisSession._(this._s, this._conn, {required this.readOnly}) : _db = _s.database, _connDb = _s.database;

  static Future<RedisSession> open(NativeConnectParams p) async {
    final s = RedisSettings.from(p);
    final conn = await _connect(s, s.database);
    final session = RedisSession._(s, conn, readOnly: p.readOnly);
    return session;
  }

  static Future<RedisConnection> _connect(RedisSettings s, int db) async {
    final c = await RedisConnection.connect(s.host, s.port, s.net);
    try {
      await _auth(c, s).timeout(s.net.timeout);
      if (db != 0) {
        try {
          await c.call(['SELECT', '$db']);
        } on RedisError catch (e) {
          throw NativeDbException('Impossibile selezionare il database $db: ${e.message}');
        }
      }
      if (s.clientName.isNotEmpty) {
        await c.raw(['CLIENT', 'SETNAME', s.clientName.replaceAll(' ', '_')]);
      }
      return c;
    } catch (e) {
      await c.close();
      if (e is TimeoutException) throw NativeDbException('Timeout durante l\'autenticazione Redis');
      rethrow;
    }
  }

  static Future<void> _auth(RedisConnection c, RedisSettings s) async {
    var user = s.user;
    var password = s.password;
    switch (s.authMethod) {
      case 'none':
        return;
      case 'azureAdDefault':
        password = await _azureToken();
        if (user.isEmpty) user = _jwtClaim(password, 'oid') ?? '';
        if (user.isEmpty) throw NativeDbException('Indica come utente l\'Object ID dell\'identità Entra ID');
      case 'awsIam':
        if (user.isEmpty) throw NativeDbException('Indica l\'utente ElastiCache abilitato all\'autenticazione IAM');
        final cache = s.opt('awsCacheName').trim().toLowerCase();
        if (cache.isEmpty) {
          throw NativeDbException('Indica il nome della cache ElastiCache (opzione "Cache ElastiCache")');
        }
        final creds = await AwsCredentials.resolve(
          accessKeyId: s.opt('awsAccessKeyId'),
          secretAccessKey: s.opt('awsSecretAccessKey'),
          profile: s.opt('awsProfile'),
        );
        final region = await AwsCredentials.region(explicit: s.opt('awsRegion'), profile: s.opt('awsProfile'));
        final url = sigv4Presign(
          method: 'GET',
          host: cache,
          query: {
            'Action': 'connect',
            'User': user,
            if (const {'sì', 'si', 'true', 'yes', '1'}.contains(s.opt('awsServerless').toLowerCase()))
              'ResourceType': 'ServerlessCache',
          },
          region: region,
          service: 'elasticache',
          credentials: creds,
          scheme: 'http',
        );
        password = url.substring('http://'.length);
    }
    if (password.isEmpty && user.isEmpty) return;
    try {
      await c.call(['AUTH', if (user.isNotEmpty) user, password]);
    } on RedisError catch (e) {
      if (user.isNotEmpty && e.message.contains('wrong number of arguments')) {
        // Redis < 6 has no ACL users.
        await c.call(['AUTH', password]);
        return;
      }
      throw NativeDbException('Autenticazione Redis fallita: ${e.message}', code: e.code, source: 'Redis');
    }
  }

  static Future<String> _azureToken() async {
    try {
      final r = await Process.run('az', [
        'account',
        'get-access-token',
        '--resource',
        'https://redis.azure.com',
        '--query',
        'accessToken',
        '-o',
        'tsv',
      ], runInShell: Platform.isWindows);
      if (r.exitCode != 0) throw NativeDbException('Azure CLI: ${r.stderr.toString().trim()}');
      final t = r.stdout.toString().trim();
      if (t.isEmpty) throw NativeDbException('Azure CLI non ha restituito un token');
      return t;
    } on ProcessException {
      throw NativeDbException('Azure CLI (az) non trovata: installala ed esegui "az login"');
    }
  }

  static String? _jwtClaim(String jwt, String claim) {
    final parts = jwt.split('.');
    if (parts.length < 2) return null;
    try {
      final json = jsonDecode(utf8.decode(base64Url.decode(base64Url.normalize(parts[1])))) as Map;
      return json[claim]?.toString();
    } catch (_) {
      return null;
    }
  }

  final RedisSettings _s;
  RedisConnection? _conn;

  /// Database selected by the user.
  int _db;

  /// Database currently selected on the connection.
  int _connDb;
  int _dbDepth = 0;
  final bool readOnly;
  int? _dbCount;
  Map<String, String>? _serverInfo;
  final Map<String, bool> _isWriteCache = {};

  @override
  String get engineName => 'Redis';

  @override
  String get completedConnectionString =>
      '${_s.net.tls ? 'rediss' : 'redis'}://${_s.user.isEmpty ? '' : '${Uri.encodeComponent(_s.user)}@'}${_s.host}:${_s.port}/$_db';

  Future<RedisConnection> _c() async {
    final c = _conn;
    if (c != null && !c.isClosed) return c;
    dropCursors();
    _conn = null;
    final n = await _connect(_s, _db);
    _conn = n;
    _connDb = _db;
    return n;
  }

  @override
  void abortConnection(String reason) {
    _conn?.abort(reason);
    _conn = null;
  }

  @override
  Future<void> closeConnection() async {
    final c = _conn;
    _conn = null;
    await c?.close();
  }

  /// Runs [fn] with database [db] selected, restoring the user database.
  Future<T> _inDb<T>(int db, Future<T> Function(RedisConnection c) fn) async {
    final c = await _c();
    if (_connDb != db) {
      await c.call(['SELECT', '$db']);
      _connDb = db;
    }
    _dbDepth++;
    try {
      return await fn(c);
    } finally {
      _dbDepth--;
      if (_dbDepth == 0 && _connDb != _db && !c.isClosed) {
        try {
          await c.call(['SELECT', '$_db']);
          _connDb = _db;
        } catch (_) {}
      }
    }
  }

  // -------------------------------------------------------------------------
  // Info / catalog
  // -------------------------------------------------------------------------

  Future<Map<String, String>> _info(String section) async {
    final r = await (await _c()).call(['INFO', section]);
    final out = <String, String>{};
    for (final l in const LineSplitter().convert(respString(r))) {
      final i = l.indexOf(':');
      if (l.startsWith('#') || i < 0) continue;
      out[l.substring(0, i)] = l.substring(i + 1).trim();
    }
    return out;
  }

  Future<int> _databaseCount() async {
    if (_dbCount != null) return _dbCount!;
    var n = 16;
    try {
      final r = await (await _c()).call(['CONFIG', 'GET', 'databases']);
      if (r is List && r.length >= 2) n = int.tryParse(respString(r[1])) ?? n;
      if (r is RespMap && r.entries.isNotEmpty) n = int.tryParse(respString(r.entries.first.value)) ?? n;
    } catch (_) {
      try {
        final ks = await _info('keyspace');
        for (final k in ks.keys) {
          final i = int.tryParse(k.replaceFirst('db', ''));
          if (i != null && i + 1 > n) n = i + 1;
        }
      } catch (_) {}
    }
    if ((_serverInfo?['redis_mode'] ?? '') == 'cluster') n = 1;
    return _dbCount = max(n, _db + 1);
  }

  @override
  Future<Map<String, Object?>> info() => exclusive(() async {
    try {
      _serverInfo ??= await _info('server');
    } catch (_) {
      _serverInfo = {};
    }
    final si = _serverInfo!;
    final valkey = si.containsKey('valkey_version') || si['server_name'] == 'valkey';
    return {
      'dbmsName': valkey ? 'Redis (Valkey)' : 'Redis',
      'dbmsVersion': si['valkey_version'] ?? si['redis_version'] ?? '',
      'driverName': 'DbCraft Redis',
      'driverVersion': redisDriverVersion,
      'serverName': '${_s.host}:${_s.port}',
      'databaseName': 'db$_db',
      'userName': _s.user,
      'identifierQuote': '',
      'catalogTerm': 'Database',
      'schemaTerm': '',
      'catalogSupported': 'Y',
      'catalogUsage': 1,
      'schemaUsage': 0,
      'proceduresSupported': 'N',
      'currentCatalog': 'db$_db',
      'catalogSeparator': '.',
      'keywords': '',
      'nativeDriver': 'redis',
      'queryLanguage': 'redis',
      'redisMode': si['redis_mode'] ?? 'standalone',
    };
  });

  static int? _dbIndex(String? name) {
    if (name == null || name.isEmpty) return null;
    return int.tryParse(name.toLowerCase().replaceFirst('db', ''));
  }

  @override
  Future<void> setCurrentCatalog(String catalog) => exclusive(() async {
    final n = _dbIndex(catalog);
    if (n == null) throw NativeDbException('Database Redis non valido: "$catalog" (usa db0, db1, …)');
    final c = await _c();
    await c.call(['SELECT', '$n']);
    _db = n;
    _connDb = n;
  });

  @override
  Future<String?> currentCatalog() async => 'db$_db';

  static bool isPattern(String key) {
    for (var i = 0; i < key.length; i++) {
      final ch = key[i];
      if (ch == '\\') {
        i++;
        continue;
      }
      if (ch == '*' || ch == '?' || ch == '[') return true;
    }
    return false;
  }

  @override
  Future<ResultPage> catalog(String function, List<String?> args) => exclusive(() async {
    String? a(int i) => i < args.length ? args[i] : null;
    bool empty(String? s) => s == null || s.isEmpty;
    switch (function) {
      case 'tables':
        final cat = a(0), sch = a(1), name = a(2), type = a(3);
        if (cat == '%' && empty(sch) && empty(name)) {
          final n = await _databaseCount();
          final names = <String>[];
          if (n <= 64) {
            names.addAll([for (var i = 0; i < n; i++) 'db$i']);
          } else {
            final ks = await _info('keyspace');
            names.addAll({'db$_db', ...ks.keys.where((k) => k.startsWith('db'))});
          }
          return catalogResult(CatalogColumns.tables, [
            for (final d in names) [d, null, null, null, null],
          ]);
        }
        if (sch == '%' && empty(cat) && empty(name)) return catalogResult(CatalogColumns.tables, const []);
        if (type == '%' && empty(cat) && empty(sch) && empty(name)) {
          return catalogResult(CatalogColumns.tables, [
            for (final t in const ['TABLE', 'STRING', 'HASH', 'LIST', 'SET', 'ZSET', 'STREAM'])
              [null, null, null, t, null],
          ]);
        }
        final db = _dbIndex(cat) ?? _db;
        final catName = 'db$db';
        if (!empty(name) && name != '%') {
          // Exact lookup (findTable): a pattern or a single key.
          return _inDb(db, (c) async {
            if (isPattern(name!)) {
              return catalogResult(CatalogColumns.tables, [
                [catName, null, name, 'TABLE', null],
              ]);
            }
            final t = respString(await c.call(['TYPE', name])).toUpperCase();
            if (t == 'NONE') return catalogResult(CatalogColumns.tables, const []);
            return catalogResult(CatalogColumns.tables, [
              [catName, null, name, t, null],
            ]);
          });
        }
        return _inDb(db, (c) async => catalogResult(CatalogColumns.tables, await _keyFolders(c, catName)));
      case 'columns':
        final db = _dbIndex(a(0)) ?? _db;
        final table = a(2) ?? '';
        final kind = await _inDb(db, (c) => _kindOf(c, table));
        final cols = _columnsFor(kind, table);
        return catalogResult(CatalogColumns.columns, [
          for (var i = 0; i < cols.length; i++)
            [
              'db$db', null, table, cols[i].name, cols[i].sqlType, cols[i].typeName, null, null, null, null, //
              i == 0 ? 0 : 1, null, null, cols[i].sqlType, null, null, i + 1, i == 0 ? 'NO' : 'YES',
            ],
        ]);
      case 'primaryKeys':
        final db = _dbIndex(a(0)) ?? _db;
        final table = a(2) ?? '';
        final kind = await _inDb(db, (c) => _kindOf(c, table));
        final key = switch (kind) {
          'listing' => 'key',
          'hash' => 'field',
          'list' => 'index',
          'set' || 'zset' => 'member',
          'stream' => 'id',
          _ => null,
        };
        return catalogResult(CatalogColumns.primaryKeys, [
          if (key != null) ['db$db', null, table, key, 1, 'PK'],
        ]);
      case 'statistics':
        return catalogResult(CatalogColumns.statistics, const []);
      case 'foreignKeys':
        return catalogResult(CatalogColumns.foreignKeys, const []);
      case 'procedures':
        return catalogResult(CatalogColumns.procedures, const []);
      default:
        return catalogResult(const ['NAME'], const []);
    }
  });

  /// Key folders and loose keys of the selected database (bounded SCAN).
  Future<List<List<Object?>>> _keyFolders(RedisConnection c, String catName) async {
    final sep = _s.separator;
    final groups = <String, int>{};
    final loose = <String>[];
    var cursor = '0';
    var scanned = 0;
    final limit = _s.scanLimit <= 0 ? 5000 : _s.scanLimit;
    do {
      final r = await c.call(['SCAN', cursor, 'COUNT', '1000']) as List;
      cursor = respString(r[0]);
      for (final k in (r[1] as List)) {
        final key = respString(k);
        scanned++;
        final i = sep.isEmpty ? -1 : key.indexOf(sep);
        if (i > 0) {
          final g = '${key.substring(0, i)}$sep*';
          groups[g] = (groups[g] ?? 0) + 1;
        } else if (loose.length < 2000) {
          loose.add(key);
        }
      }
    } while (cursor != '0' && scanned < limit);
    final partial = cursor != '0';
    final rows = <List<Object?>>[];
    groups.forEach((g, n) => rows.add([catName, null, g, 'TABLE', '$n chiavi${partial ? ' (campione)' : ''}']));
    final types = await c.pipeline([
      for (final k in loose) ['TYPE', k],
    ]);
    for (var i = 0; i < loose.length; i++) {
      final t = respString(types[i]).toUpperCase();
      if (t == 'NONE' || types[i] is RedisError) continue;
      rows.add([catName, null, loose[i], t, null]);
    }
    return rows;
  }

  /// 'listing' for patterns / missing keys, otherwise the key type.
  Future<String> _kindOf(RedisConnection c, String key) async {
    if (isPattern(key)) return 'listing';
    final t = respString(await c.call(['TYPE', key])).toLowerCase();
    return t == 'none' ? 'listing' : t;
  }

  static List<ColumnInfo> _columnsFor(
    String kind,
    String table, {
    String? catalog,
    List<String> streamFields = const [],
  }) {
    final spec = switch (kind) {
      'listing' => [('key', SQL_VARCHAR), ('type', SQL_VARCHAR), ('ttl', SQL_BIGINT), ('size', SQL_BIGINT)],
      'hash' => [('field', SQL_VARCHAR), ('value', SQL_LONGVARCHAR)],
      'list' => [('index', SQL_BIGINT), ('value', SQL_LONGVARCHAR)],
      'set' => [('member', SQL_VARCHAR)],
      'zset' => [('member', SQL_VARCHAR), ('score', SQL_DOUBLE)],
      'stream' => [('id', SQL_VARCHAR), for (final f in streamFields) (f, SQL_VARCHAR)],
      _ => [('value', SQL_LONGVARCHAR)],
    };
    return nativeColumns(spec, table: table, catalog: catalog);
  }

  // -------------------------------------------------------------------------
  // Execution
  // -------------------------------------------------------------------------

  @override
  Future<List<StatementOutcome>> runScript(String sql, List<Object?> params, int fetchSize, int queryTimeoutSec) async {
    final text = sql.trim();
    if (text.isEmpty) return [StatementOutcome.update(-1)];
    // The native SELECT <db> is not the SQL SELECT.
    final nativeSelect = RegExp(r'^select\s+\d+\s*;?$', caseSensitive: false).hasMatch(text);
    final subset = nativeSelect ? null : parseSqlSubset(text, params: params);
    if (subset != null) return [await _runSubset(subset, fetchSize)];
    final out = <StatementOutcome>[];
    for (final line in splitRedisScript(text)) {
      final args = tokenizeRedisCommand(line);
      if (args.isEmpty) continue;
      out.add(await _command(args));
    }
    return out.isEmpty ? [StatementOutcome.update(-1)] : out;
  }

  Future<bool> _isWrite(RedisConnection c, List<String> args) async {
    final name = args.first.toUpperCase();
    if (redisWriteCommands.contains(name)) return true;
    final subs = _writeSubcommands[name];
    if (subs != null) return args.length > 1 && subs.contains(args[1].toUpperCase());
    final cached = _isWriteCache[name];
    if (cached != null) return cached;
    var w = false;
    try {
      final r = await c.call(['COMMAND', 'INFO', name.toLowerCase()]);
      if (r is List && r.isNotEmpty && r.first is List) {
        final flags = (r.first as List).length > 2 ? (r.first as List)[2] : null;
        final list = flags is List ? flags : (flags is RespSet ? flags.items : const []);
        w = list.map(respString).contains('write');
      }
    } catch (_) {}
    return _isWriteCache[name] = w;
  }

  Future<StatementOutcome> _command(List<String> args) async {
    final name = args.first.toUpperCase();
    if (_unsupportedCommands.contains(name)) {
      throw NativeDbException('Il comando $name non è supportato nell\'editor (occuperebbe la connessione)');
    }
    final c = await _c();
    if (readOnly && await _isWrite(c, args)) throw readOnlyError(name);
    final reply = await c.raw(args);
    if (reply is RedisError) throw reply;
    if (name == 'SELECT') {
      _db = int.tryParse(args.length > 1 ? args[1] : '') ?? _db;
      _connDb = _db;
      return StatementOutcome.update(-1, messages: ['Database corrente: db$_db']);
    }
    return renderRedisReply(args, reply);
  }

  // -- SQL subset -------------------------------------------------------------

  (int, String) _target(SqlTarget t) {
    final m = RegExp(r'^db(\d+)\.(.+)$', dotAll: true).firstMatch(t.raw);
    if (m != null) return (int.parse(m.group(1)!), m.group(2)!);
    return (_db, t.raw);
  }

  Future<StatementOutcome> _runSubset(SqlSubsetStatement st, int fetchSize) async {
    final (db, key) = _target(st.target);
    final catName = 'db$db';
    switch (st) {
      case SubsetSelect():
        return _inDb(db, (c) async {
          final kind = await _kindOf(c, key);
          if (st.isCount) {
            final n = await _count(c, kind, key, st.where);
            return StatementOutcome.rows(nativeColumns([('COUNT(*)', SQL_BIGINT)]), [
              [n],
            ]);
          }
          if (st.whereText.trim().startsWith('{')) {
            throw NativeDbException('Filtro JSON non supportato su Redis: usa condizioni come field = \'x\'');
          }
          var pattern = key;
          if (kind == 'listing' && key == '*') pattern = _globFromWhere(st.where) ?? key;
          var inner = await _contentCursor(c, db, kind, key, pattern, catName, fetchSize);
          if (st.where != null ||
              st.orderBy.isNotEmpty ||
              st.limit != null ||
              st.offset != null ||
              st.columns != null) {
            inner = _FilterCursor(inner, st.where, st.columns, st.limit, st.offset);
          }
          if (st.orderBy.isNotEmpty) {
            final rows = await inner.fetch(100000);
            final more = inner.hasMore;
            await inner.close();
            final cols = inner.columns;
            int idx(String f) => cols.indexWhere((c) => c.name.toLowerCase() == f.toLowerCase());
            rows.sort((a, b) {
              for (final o in st.orderBy) {
                final i = idx(o.field);
                if (i < 0) continue;
                final r = _cmp(a[i], b[i]);
                if (r != 0) return o.descending ? -r : r;
              }
              return 0;
            });
            return StatementOutcome.rows(
              cols,
              rows,
              messages: [if (more) 'Ordinamento applicato alle prime 100000 righe'],
            );
          }
          return StatementOutcome.cursor(inner);
        });
      case SubsetUpdate():
        if (readOnly) throw readOnlyError('UPDATE');
        return _inDb(db, (c) => _update(c, key, st));
      case SubsetInsert():
        if (readOnly) throw readOnlyError('INSERT');
        return _inDb(db, (c) => _insert(c, key, st));
      case SubsetDelete():
        if (readOnly) throw readOnlyError('DELETE');
        return _inDb(db, (c) => _delete(c, key, st));
    }
  }

  static int _cmp(Object? a, Object? b) {
    if (a == null) return b == null ? 0 : -1;
    if (b == null) return 1;
    if (a is num && b is num) return a.compareTo(b);
    return a.toString().compareTo(b.toString());
  }

  /// `key LIKE 'user:%'` / `key = 'x'` → SCAN MATCH pattern.
  static String? _globFromWhere(SqlExpr? e) {
    if (e is SqlCmp && e.field.toLowerCase() == 'key' && !e.negated && e.value is String) {
      if (e.op == 'like') return likeToGlob(e.value as String);
      if (e.op == '=') return likeToGlob((e.value as String).replaceAll('%', r'\%').replaceAll('_', r'\_'));
    }
    if (e is SqlAnd) {
      for (final i in e.items) {
        final g = _globFromWhere(i);
        if (g != null) return g;
      }
    }
    return null;
  }

  Future<int> _count(RedisConnection c, String kind, String key, SqlExpr? where) async {
    if (where == null) {
      switch (kind) {
        case 'listing':
          if (key == '*') return (await c.call(['DBSIZE'])) as int;
          var n = 0;
          var cursor = '0';
          do {
            final r = await c.call(['SCAN', cursor, 'MATCH', key, 'COUNT', '1000']) as List;
            cursor = respString(r[0]);
            n += (r[1] as List).length;
          } while (cursor != '0');
          return n;
        case 'string':
          return 1;
        case 'hash':
          return (await c.call(['HLEN', key])) as int;
        case 'list':
          return (await c.call(['LLEN', key])) as int;
        case 'set':
          return (await c.call(['SCARD', key])) as int;
        case 'zset':
          return (await c.call(['ZCARD', key])) as int;
        case 'stream':
          return (await c.call(['XLEN', key])) as int;
      }
      return 1;
    }
    final cur = _FilterCursor(
      await _contentCursor(c, _connDb, kind, key, key, 'db$_connDb', 1000),
      where,
      null,
      null,
      null,
    );
    var n = 0;
    while (cur.hasMore) {
      n += (await cur.fetch(1000)).length;
    }
    return n;
  }

  Future<NativeCursor> _contentCursor(
    RedisConnection c,
    int db,
    String kind,
    String key,
    String pattern,
    String catName,
    int fetchSize,
  ) async {
    switch (kind) {
      case 'listing':
        return _RedisCursor(this, c, db, _columnsFor('listing', key, catalog: catName), (cur, n) async {
          final keys = <String>[];
          var cursor = cur ?? '0';
          var rounds = 0;
          do {
            final r = await c.call(['SCAN', cursor, 'MATCH', pattern, 'COUNT', '${max(n, 100)}']) as List;
            cursor = respString(r[0]);
            keys.addAll([for (final k in (r[1] as List)) respString(k)]);
            rounds++;
          } while (cursor != '0' && keys.length < n && rounds < 100);
          return (await _describeKeys(c, keys), cursor == '0' ? null : cursor);
        });
      case 'hash':
        return _RedisCursor(this, c, db, _columnsFor('hash', key, catalog: catName), (cur, n) async {
          final r = await c.call(['HSCAN', key, cur ?? '0', 'COUNT', '${max(n, 100)}']) as List;
          final items = r[1] as List;
          final next = respString(r[0]);
          return (
            [
              for (var i = 0; i + 1 < items.length; i += 2) [respString(items[i]), respText(items[i + 1])],
            ],
            next == '0' ? null : next,
          );
        });
      case 'set':
        return _RedisCursor(this, c, db, _columnsFor('set', key, catalog: catName), (cur, n) async {
          final r = await c.call(['SSCAN', key, cur ?? '0', 'COUNT', '${max(n, 100)}']) as List;
          final next = respString(r[0]);
          return (
            [
              for (final m in (r[1] as List)) [respText(m)],
            ],
            next == '0' ? null : next,
          );
        });
      case 'zset':
        return _RedisCursor(this, c, db, _columnsFor('zset', key, catalog: catName), (cur, n) async {
          final start = int.parse(cur ?? '0');
          final r = await c.call(['ZRANGE', key, '$start', '${start + n - 1}', 'WITHSCORES']) as List;
          final rows = <List<Object?>>[];
          for (var i = 0; i + 1 < r.length; i += 2) {
            final s = r[i + 1];
            rows.add([respText(r[i]), s is double ? s : double.tryParse(respString(s))]);
          }
          return (rows, rows.length < n ? null : '${start + n}');
        });
      case 'list':
        return _RedisCursor(this, c, db, _columnsFor('list', key, catalog: catName), (cur, n) async {
          final start = int.parse(cur ?? '0');
          final r = await c.call(['LRANGE', key, '$start', '${start + n - 1}']) as List;
          return (
            [
              for (var i = 0; i < r.length; i++) [start + i, respText(r[i])],
            ],
            r.length < n ? null : '${start + n}',
          );
        });
      case 'stream':
        final first = await c.call(['XRANGE', key, '-', '+', 'COUNT', '$fetchSize']) as List;
        final fields = <String>[];
        for (final e in first) {
          final kv = (e as List)[1] as List? ?? const [];
          for (var i = 0; i < kv.length; i += 2) {
            final f = respString(kv[i]);
            if (!fields.contains(f) && f != 'id') fields.add(f);
          }
        }
        List<List<Object?>> rowsOf(List entries) => [
          for (final e in entries)
            () {
              final kv = (e as List)[1] as List? ?? const [];
              final m = <String, Object?>{};
              for (var i = 0; i + 1 < kv.length; i += 2) {
                m[respString(kv[i])] = respText(kv[i + 1]);
              }
              return [respString(e[0]), for (final f in fields) m[f]];
            }(),
        ];
        var firstPage = true;
        return _RedisCursor(this, c, db, _columnsFor('stream', key, catalog: catName, streamFields: fields), (
          cur,
          n,
        ) async {
          List entries;
          if (firstPage && n <= first.length) {
            firstPage = false;
            entries = first.take(n).toList();
          } else {
            firstPage = false;
            entries = await c.call(['XRANGE', key, cur == null ? '-' : '($cur', '+', 'COUNT', '$n']) as List;
          }
          final rows = rowsOf(entries);
          return (rows, rows.length < n || rows.isEmpty ? null : rows.last.first.toString());
        });
      case 'rejson-rl':
        final v = await c.call(['JSON.GET', key]);
        return ListCursor(_columnsFor('string', key, catalog: catName), [
          [respText(v)],
        ]);
      case 'string':
        final v = await c.call(['GET', key]);
        return ListCursor(_columnsFor('string', key, catalog: catName), [
          [respText(v)],
        ]);
      default:
        return ListCursor(nativeColumns([('type', SQL_VARCHAR)]), [
          [kind],
        ]);
    }
  }

  /// type, TTL (seconds, -1 = none) and size of each key.
  Future<List<List<Object?>>> _describeKeys(RedisConnection c, List<String> keys) async {
    if (keys.isEmpty) return [];
    final r = await c.pipeline([
      for (final k in keys) ...[
        ['TYPE', k],
        ['TTL', k],
      ],
    ]);
    final types = [for (var i = 0; i < keys.length; i++) respString(r[i * 2]).toLowerCase()];
    final sizeCmds = <List<Object>>[];
    for (var i = 0; i < keys.length; i++) {
      final cmd = switch (types[i]) {
        'string' => 'STRLEN',
        'hash' => 'HLEN',
        'list' => 'LLEN',
        'set' => 'SCARD',
        'zset' => 'ZCARD',
        'stream' => 'XLEN',
        _ => 'EXISTS',
      };
      sizeCmds.add([cmd, keys[i]]);
    }
    final sizes = await c.pipeline(sizeCmds);
    return [
      for (var i = 0; i < keys.length; i++)
        if (types[i] != 'none')
          [keys[i], types[i], r[i * 2 + 1] is int ? r[i * 2 + 1] : null, sizes[i] is int ? sizes[i] : null],
    ];
  }

  // -- DML ---------------------------------------------------------------------

  Map<String, Object?> _keyOf(SqlExpr? where, String what) {
    final eq = sqlEqualities(where);
    if (eq == null) throw NativeDbException('$what: su Redis la condizione WHERE deve essere del tipo campo = valore');
    return {for (final e in eq.entries) e.key.toLowerCase(): e.value};
  }

  static String _str(Object? v) => switch (v) {
    null => '',
    Uint8List() => latin1.decode(v),
    double() => v == v.truncateToDouble() && v.abs() < 1e15 ? v.toInt().toString() : v.toString(),
    _ => v.toString(),
  };

  static Object _arg(Object? v) => v is Uint8List ? v : _str(v);

  Future<StatementOutcome> _update(RedisConnection c, String key, SubsetUpdate st) async {
    final kind = await _kindOf(c, key);
    final w = _keyOf(st.where, 'UPDATE');
    final set = {for (final (k, v) in st.assignments) k.toLowerCase(): v};
    switch (kind) {
      case 'listing':
        final k = w['key'];
        if (k == null) throw NativeDbException('UPDATE: indica la chiave (WHERE key = …)');
        var name = _str(k);
        var n = 0;
        if (set.containsKey('key') && _str(set['key']) != name) {
          await c.call(['RENAME', name, _str(set['key'])]);
          name = _str(set['key']);
          n = 1;
        }
        if (set.containsKey('ttl')) {
          final ttl = int.tryParse(_str(set['ttl']));
          if (ttl == null || ttl < 0) {
            await c.call(['PERSIST', name]);
          } else {
            await c.call(['EXPIRE', name, '$ttl']);
          }
          n = 1;
        }
        return StatementOutcome.update(n);
      case 'string':
      case 'none':
        if (!set.containsKey('value')) throw NativeDbException('UPDATE: colonna value attesa');
        final r = await c.raw(['SET', key, _arg(set['value']), 'KEEPTTL']);
        if (r is RedisError) await c.call(['SET', key, _arg(set['value'])]);
        return StatementOutcome.update(1);
      case 'hash':
        final f = w['field'];
        if (f == null) throw NativeDbException('UPDATE: indica il campo (WHERE field = …)');
        final newField = set.containsKey('field') ? _str(set['field']) : _str(f);
        final value = set.containsKey('value') ? set['value'] : await c.call(['HGET', key, _str(f)]);
        if (newField != _str(f)) await c.call(['HDEL', key, _str(f)]);
        await c.call(['HSET', key, newField, _arg(value)]);
        return StatementOutcome.update(1);
      case 'list':
        final i = w['index'];
        if (i == null) throw NativeDbException('UPDATE: indica la posizione (WHERE index = …)');
        await c.call(['LSET', key, _str(i), _arg(set['value'])]);
        return StatementOutcome.update(1);
      case 'set':
        final m = w['member'];
        if (m == null) throw NativeDbException('UPDATE: indica il membro (WHERE member = …)');
        final removed = await c.call(['SREM', key, _arg(m)]);
        await c.call(['SADD', key, _arg(set['member'] ?? m)]);
        return StatementOutcome.update(removed == 0 ? 0 : 1);
      case 'zset':
        final m = w['member'];
        if (m == null) throw NativeDbException('UPDATE: indica il membro (WHERE member = …)');
        final score = set.containsKey('score')
            ? _str(set['score'])
            : respString(await c.call(['ZSCORE', key, _arg(m)]));
        if (set.containsKey('member') && _str(set['member']) != _str(m)) {
          await c.call(['ZREM', key, _arg(m)]);
        }
        await c.call(['ZADD', key, score, _arg(set['member'] ?? m)]);
        return StatementOutcome.update(1);
    }
    throw NativeDbException('UPDATE non supportato per il tipo $kind');
  }

  Future<StatementOutcome> _insert(RedisConnection c, String key, SubsetInsert st) async {
    final kind = await _kindOf(c, key);
    var n = 0;
    for (final row in st.rows) {
      final v = {for (var i = 0; i < st.columns.length && i < row.length; i++) st.columns[i].toLowerCase(): row[i]};
      final effective = kind == 'listing' && !isPattern(key)
          ? (v.containsKey('field')
                ? 'hash'
                : (v.containsKey('score')
                      ? 'zset'
                      : (v.containsKey('member') ? 'set' : (v.containsKey('index') ? 'list' : 'string'))))
          : kind;
      switch (effective) {
        case 'string':
          await c.call(['SET', key, _arg(v['value'])]);
        case 'hash':
          await c.call(['HSET', key, _str(v['field']), _arg(v['value'])]);
        case 'list':
          await c.call(['RPUSH', key, _arg(v['value'])]);
        case 'set':
          await c.call(['SADD', key, _arg(v['member'])]);
        case 'zset':
          await c.call(['ZADD', key, _str(v['score'] ?? 0), _arg(v['member'])]);
        case 'stream':
          final fields = [
            for (final e in v.entries)
              if (e.key != 'id' && e.value != null) ...[e.key, _arg(e.value)],
          ];
          await c.call(['XADD', key, _str(v['id']).isEmpty ? '*' : _str(v['id']), ...fields]);
        case 'listing':
          final k = _str(v['key']);
          if (k.isEmpty) throw NativeDbException('INSERT: indica la chiave');
          final t = (_str(v['type']).isEmpty ? 'string' : _str(v['type'])).toLowerCase();
          if (t != 'string') {
            throw NativeDbException('INSERT nell\'elenco chiavi: solo chiavi stringa, usa un comando Redis per $t');
          }
          await c.call(['SET', k, '']);
        default:
          throw NativeDbException('INSERT non supportato per il tipo $effective');
      }
      n++;
    }
    return StatementOutcome.update(n);
  }

  Future<StatementOutcome> _delete(RedisConnection c, String key, SubsetDelete st) async {
    final kind = await _kindOf(c, key);
    if (st.where == null) {
      if (kind == 'listing') throw NativeDbException('DELETE senza WHERE su un elenco di chiavi non consentito');
      return StatementOutcome.update((await c.call(['DEL', key])) as int);
    }
    final w = _keyOf(st.where, 'DELETE');
    switch (kind) {
      case 'listing':
        return StatementOutcome.update((await c.call(['DEL', _str(w['key'])])) as int);
      case 'string':
        return StatementOutcome.update((await c.call(['DEL', key])) as int);
      case 'hash':
        return StatementOutcome.update((await c.call(['HDEL', key, _str(w['field'])])) as int);
      case 'set':
        return StatementOutcome.update((await c.call(['SREM', key, _arg(w['member'])])) as int);
      case 'zset':
        return StatementOutcome.update((await c.call(['ZREM', key, _arg(w['member'])])) as int);
      case 'stream':
        return StatementOutcome.update((await c.call(['XDEL', key, _str(w['id'])])) as int);
      case 'list':
        // Mark the element and remove the marker (LREM by value would remove
        // duplicates too).
        final marker = '__dbcraft_deleted_${DateTime.now().microsecondsSinceEpoch}__';
        await c.call(['LSET', key, _str(w['index']), marker]);
        return StatementOutcome.update((await c.call(['LREM', key, '1', marker])) as int);
    }
    throw NativeDbException('DELETE non supportato per il tipo $kind');
  }
}

/// Paged cursor driven by a continuation token (SCAN cursor, offset, last id).
class _RedisCursor implements NativeCursor {
  _RedisCursor(this.session, this.conn, this.db, this.columns, this.page);

  final RedisSession session;
  final RedisConnection conn;
  final int db;
  @override
  final List<ColumnInfo> columns;
  final Future<(List<List<Object?>>, String?)> Function(String? token, int n) page;
  String? _token;
  bool _done = false;
  final List<List<Object?>> _buffer = [];

  @override
  bool get hasMore => !_done || _buffer.isNotEmpty;

  @override
  Future<List<List<Object?>>> fetch(int count) async {
    final want = count <= 0 ? 1 << 30 : count;
    while (_buffer.length < want && !_done) {
      if (conn.isClosed) {
        _done = true;
        throw NativeDbException('Cursore non più valido: la connessione è stata chiusa');
      }
      final n = min(max(want - _buffer.length, 1), 1000);
      final (rows, next) = await session._inDb(db, (_) => page(_token, n));
      _buffer.addAll(rows);
      _token = next;
      if (next == null) _done = true;
    }
    final take = min(want, _buffer.length);
    final out = _buffer.sublist(0, take);
    _buffer.removeRange(0, take);
    return out;
  }

  @override
  Future<void> close() async {
    _done = true;
    _buffer.clear();
  }
}

/// Client side WHERE / projection / LIMIT / OFFSET over another cursor.
class _FilterCursor implements NativeCursor {
  _FilterCursor(this.inner, this.where, List<String>? select, this.limit, this.offset) {
    final cols = inner.columns;
    if (select == null) {
      _idx = [for (var i = 0; i < cols.length; i++) i];
    } else {
      _idx = [];
      for (final s in select) {
        final i = cols.indexWhere((c) => c.name.toLowerCase() == s.toLowerCase());
        if (i < 0) {
          throw NativeDbException('Colonna "$s" inesistente (disponibili: ${cols.map((c) => c.name).join(', ')})');
        }
        _idx.add(i);
      }
    }
    columns = [
      for (var j = 0; j < _idx.length; j++)
        ColumnInfo(
          index: j + 1,
          name: cols[_idx[j]].name,
          sqlType: cols[_idx[j]].sqlType,
          typeName: cols[_idx[j]].typeName,
          baseTable: cols[_idx[j]].baseTable,
          baseColumn: cols[_idx[j]].baseColumn,
          catalog: cols[_idx[j]].catalog,
        ),
    ];
  }

  final NativeCursor inner;
  final SqlExpr? where;
  final int? limit;
  final int? offset;
  late final List<int> _idx;
  @override
  late final List<ColumnInfo> columns;
  int _skipped = 0;
  int _returned = 0;
  final List<List<Object?>> _pending = [];

  bool get _limitReached => limit != null && _returned >= limit!;

  @override
  bool get hasMore => !_limitReached && (_pending.isNotEmpty || inner.hasMore);

  @override
  Future<List<List<Object?>>> fetch(int count) async {
    final out = <List<Object?>>[];
    final names = [for (final c in inner.columns) c.name.toLowerCase()];
    var rounds = 0;
    while ((count <= 0 || out.length < count) && !_limitReached) {
      if (_pending.isEmpty) {
        if (!inner.hasMore || rounds++ > 200) break;
        _pending.addAll(await inner.fetch(max(count, 200)));
        continue;
      }
      final row = _pending.removeAt(0);
      final w = where;
      if (w != null &&
          !evalSqlExpr(w, (f) {
            final i = names.indexOf(f.toLowerCase());
            return i < 0 ? null : row[i];
          })) {
        continue;
      }
      if (offset != null && _skipped < offset!) {
        _skipped++;
        continue;
      }
      out.add([for (final i in _idx) row[i]]);
      _returned++;
    }
    return out;
  }

  @override
  Future<void> close() => inner.close();
}

// ---------------------------------------------------------------------------
// Reply rendering (public for tests)
// ---------------------------------------------------------------------------

bool _isArray(Object? v) => v is List && v is! Uint8List;

String _json(Object? v) => compactJson(
  v,
  special: (x) => switch (x) {
    Uint8List() => jsonEncode(respString(x)),
    RespMap() => compactJson({
      for (final e in x.entries) respString(e.key): e.value,
    }, special: (y) => y is Uint8List ? jsonEncode(respString(y)) : null),
    RespSet() => compactJson(x.items, special: (y) => y is Uint8List ? jsonEncode(respString(y)) : null),
    _ => null,
  },
);

Object? _cell(Object? v) => switch (v) {
  null => null,
  Uint8List() => respText(v),
  int() || double() || String() => v,
  bool() => v ? 'true' : 'false',
  _ => _json(v),
};

/// Converts the reply of a command into a grid.
StatementOutcome renderRedisReply(List<String> args, Object? reply) {
  final name = args.first.toUpperCase();
  final sub = args.length > 1 ? args[1].toUpperCase() : '';
  final upperArgs = args.map((e) => e.toUpperCase()).toSet();
  StatementOutcome pairs(
    List items,
    String k,
    String v, {
    int vType = SQL_LONGVARCHAR,
    List<String> messages = const [],
  }) {
    return StatementOutcome.rows(nativeColumns([(k, SQL_VARCHAR), (v, vType)]), [
      for (var i = 0; i + 1 < items.length; i += 2)
        [respString(items[i]), vType == SQL_DOUBLE ? double.tryParse(respString(items[i + 1])) : _cell(items[i + 1])],
    ], messages: messages);
  }

  StatementOutcome values(List items, {String column = 'value', List<String> messages = const []}) =>
      StatementOutcome.rows(nativeColumns([('#', SQL_INTEGER), (column, SQL_LONGVARCHAR)]), [
        for (var i = 0; i < items.length; i++) [i + 1, _cell(items[i])],
      ], messages: messages);

  if (reply is RespMap) {
    return StatementOutcome.rows(nativeColumns([('field', SQL_VARCHAR), ('value', SQL_LONGVARCHAR)]), [
      for (final e in reply.entries) [respString(e.key), _cell(e.value)],
    ]);
  }
  if (reply is RespSet) return values(reply.items);
  if (_isArray(reply)) {
    reply as List;
    if (const {'SCAN', 'HSCAN', 'SSCAN', 'ZSCAN'}.contains(name) && reply.length == 2 && _isArray(reply[1])) {
      final next = respString(reply[0]);
      final items = reply[1] as List;
      final msg = ['Cursore successivo: $next${next == '0' ? ' (scansione completata)' : ''}'];
      if (name == 'HSCAN' && !upperArgs.contains('NOVALUES')) return pairs(items, 'field', 'value', messages: msg);
      if (name == 'ZSCAN') return pairs(items, 'member', 'score', vType: SQL_DOUBLE, messages: msg);
      return values(items, column: name == 'SCAN' ? 'key' : 'member', messages: msg);
    }
    if (name == 'HGETALL' ||
        (name == 'CONFIG' && sub == 'GET') ||
        (name == 'HRANDFIELD' && upperArgs.contains('WITHVALUES'))) {
      return pairs(reply, name == 'CONFIG' ? 'parameter' : 'field', 'value');
    }
    if (upperArgs.contains('WITHSCORES') ||
        (const {'ZPOPMIN', 'ZPOPMAX'}.contains(name) && reply.isNotEmpty && !_isArray(reply.first))) {
      if (reply.isNotEmpty && _isArray(reply.first)) {
        // RESP3 style [[member, score], …]
        return StatementOutcome.rows(nativeColumns([('member', SQL_VARCHAR), ('score', SQL_DOUBLE)]), [
          for (final p in reply) [respString((p as List)[0]), double.tryParse(respString(p[1]))],
        ]);
      }
      return pairs(reply, 'member', 'score', vType: SQL_DOUBLE);
    }
    if ((name == 'XRANGE' || name == 'XREVRANGE') && reply.every((e) => _isArray(e) && (e as List).length == 2)) {
      return StatementOutcome.rows(nativeColumns([('id', SQL_VARCHAR), ('fields', SQL_LONGVARCHAR)]), [
        for (final e in reply)
          [
            respString((e as List)[0]),
            _json({
              for (var i = 0; i + 1 < (e[1] as List).length; i += 2)
                respString((e[1] as List)[i]): respString((e[1] as List)[i + 1]),
            }),
          ],
      ]);
    }
    if ((name == 'MEMORY' && sub == 'STATS') || (name == 'XINFO' && sub == 'STREAM')) {
      return pairs(reply, 'field', 'value');
    }
    return values(reply);
  }
  // Scalars
  if (name == 'INFO' && reply is Uint8List) {
    final rows = <List<Object?>>[];
    var section = '';
    for (final l in const LineSplitter().convert(respString(reply))) {
      if (l.startsWith('#')) {
        section = l.substring(1).trim();
        continue;
      }
      final i = l.indexOf(':');
      if (i < 0) continue;
      rows.add([section, l.substring(0, i), l.substring(i + 1).trim()]);
    }
    return StatementOutcome.rows(
      nativeColumns([('section', SQL_VARCHAR), ('key', SQL_VARCHAR), ('value', SQL_VARCHAR)]),
      rows,
    );
  }
  if (name == 'CLIENT' && (sub == 'LIST' || sub == 'INFO') && reply is Uint8List) {
    final lines = const LineSplitter().convert(respString(reply)).where((l) => l.trim().isNotEmpty).toList();
    final keys = <String>[];
    final maps = <Map<String, String>>[];
    for (final l in lines) {
      final m = <String, String>{};
      for (final part in l.split(' ')) {
        final i = part.indexOf('=');
        if (i <= 0) continue;
        final k = part.substring(0, i);
        if (!keys.contains(k)) keys.add(k);
        m[k] = part.substring(i + 1);
      }
      maps.add(m);
    }
    return StatementOutcome.rows(nativeColumns([for (final k in keys) (k, SQL_VARCHAR)]), [
      for (final m in maps) [for (final k in keys) m[k]],
    ]);
  }
  final v = _cell(reply);
  return StatementOutcome.rows(
    nativeColumns([('value', v is int ? SQL_BIGINT : (v is double ? SQL_DOUBLE : SQL_LONGVARCHAR))]),
    [
      [v],
    ],
  );
}
